Evaluate the JavaScript Space Invaders game implementation on a scale of 0-10 points:

**Game Completeness (4 points)**: Does it implement all core Space Invaders features - player movement, shooting, enemy formations, collision detection, and proper win/lose conditions?

**Gameplay Quality (3 points)**: Are the controls responsive? Is the difficulty balanced? Do enemies move in proper formation and shoot back? Are collision mechanics accurate?

**Visual & Audio Feedback (2 points)**: Does it include clear sprites, smooth animations, explosion effects, and score display? Is the visual feedback satisfying?

**Performance & Code Quality (1 point)**: Does it run smoothly at 60 FPS with efficient game loop and well-structured code?

Solution A: function playSpaceInvaders(canvasId) {  
    const canvas = document.getElementById(canvasId);  
    const ctx = canvas.getContext('2d');  

    const WIDTH = canvas.width;  
    const HEIGHT = canvas.height;  

    const KEY = { LEFT: 37, RIGHT: 39, SPACE: 32 };  
    const keys = {};  

    window.addEventListener('keydown', e => { keys[e.keyCode] = true; });  
    window.addEventListener('keyup', e => { keys[e.keyCode] = false; });  

    let score = 0;  
    let level = 1;  
    let gameOver = false;  

    // Player  
    const player = {  
        x: WIDTH / 2,  
        y: HEIGHT - 40,  
        w: 30,  
        h: 20,  
        speed: 5,  
        bullets: [],  
        fireCooldown: 0  
    };  

    // Enemy grid
    const enemy = {  
        rows: 3,  
        cols: 7,  
        w: 32,  
        h: 20,  
        x: 50,  
        y: 50,  
        dx: 20,  
        dy: 10,  
        speed: 0.5,  
        bullets: [],  
        keyCooldown: 0  
    };  

    const bullets = []; // All bullets (both player & enemy)  
    const explosions = []; // Explosions  

    function spawnEnemies() {  
        enemy.grid = [];  
        for (let r = 0; r < enemy.rows; r++) {  
            const row = [];  
            for (let c = 0; c < enemy.cols; c++) {  
                row.push({  
                    x: enemy.x + c * (enemy.w + 10),  
                    y: enemy.y + r * (enemy.h + 10),  
                    w: enemy.w,  
                    h: enemy.h,  
                    alive: true  
                });  
            }  
            enemy.grid.push(row);  
        }  
    }  

    spawnEnemies();  

    function drawPlayer() {  
        ctx.fillStyle = '#0f0';  
        ctx.beginPath();  
        ctx.moveTo(player.x, player.y - player.h / 2);  
        ctx.lineTo(player.x - player.w / 2, player.y + player.h / 2);  
        ctx.lineTo(player.x + player.w / 2, player.y + player.h / 2);  
        ctx.closePath();  
        ctx.fill();  
    }  

    function drawEnemies() {  
        ctx.fillStyle = '#f00';  
        for (const row of enemy.grid) {  
            for (const e of row) {  
                if (e.alive) {  
                    ctx.fillRect(e.x - e.w / 2, e.y - e.h / 2, e.w, e.h);  
                }  
            }  
        }  
    }  

    function drawBullets() {  
        ctx.fillStyle = '#fff';  
        for (const b of bullets) {  
            ctx.fillRect(b.x - b.w / 2, b.y - b.h / 2, b.w, b.h);  
        }  
    }  

    function drawExplosions() {  
        for (const e of explosions) {  
            ctx.fillStyle = `rgba(255,${Math.floor(255 * e.alpha)},0,${e.alpha})`;  
            ctx.beginPath();  
            ctx.arc(e.x, e.y, e.size, 0, Math.PI * 2);  
            ctx.fill();  
        }  
    }  

    function drawHUD() {  
        ctx.fillStyle = '#fff';  
        ctx.font = '18px monospace';  
        ctx.fillText(`Score: ${score}  Level: ${level}`, 10, 20);  
    }  

    function updatePlayer() {  
        if (keys[KEY.LEFT] && player.x - player.w / 2 > 0) player.x -= player.speed;  
        if (keys[KEY.RIGHT] && player.x + player.w / 2 < WIDTH) player.x += player.speed;  

        if (keys[KEY.SPACE] && player.fireCooldown <= 0) {  
            bullets.push({  
                x: player.x,  
                y: player.y - player.h / 2,  
                w: 4,  
                h: 10,  
                dy: -8,  
                source: 'player'  
            });  
            player.fireCooldown = 15;  
        }  

        if (player.fireCooldown > 0) player.fireCooldown--;  
    }  

    function updateEnemies() {  
        // Move horizontally  
        enemy.x += enemy.dx * enemy.speed;  
        let hitEdge = false;  
        for (const row of enemy.grid) {  
            for (const e of row) {  
                if (e.alive) {  
                    const newX = e.x + enemy.dx * enemy.speed;  
                    if (newX - e.w / 2 < 0 || newX + e.w / 2 > WIDTH) {  
                        hitEdge = true; break;  
                    }  
                }  
            }  
            if (hitEdge) break;  
        }  
        if (hitEdge) {  
            enemy.dx *= -1;  
            enemy.y += enemy.dy;  
        }  

        // Enemy shooting  
        enemy.keyCooldown--;  
        if (enemy.keyCooldown <= 0) {  
            // Pick a random alive enemy  
            const alive = [];  
            for (const row of enemy.grid) {  
                for (const e of row) {  
                    if (e.alive) alive.push(e);  
                }  
            }  
            if (alive.length > 0) {  
                const shooter = alive[Math.floor(Math.random() * alive.length)];  
                bullets.push({  
                    x: shooter.x,  
                    y: shooter.y + shooter.h / 2,  
                    w: 4,  
                    h: 10,  
                    dy: 5,  
                    source: 'enemy'  
                });  
            }  
            enemy.keyCooldown = 200;  
        }  

        // Check if any enemy reached bottom → lose  
        for (const row of enemy.grid) {  
            for (const e of row) {  
                if (e.alive && e.y + e.h / 2 >= HEIGHT - 50) {  
                    gameOver = true;  
                }  
            }  
        }  
    }  

    function updateBullets() {  
        for (let i = bullets.length - 1; i >= 0; i--) {  
            const b = bullets[i];  
            b.y += b.dy;  
            // Remove off-screen bullets  
            if (b.y < 0 || b.y > HEIGHT) {  
                bullets.splice(i, 1);  
                continue;  
            }  
            // Collision detection  
            if (b.source === 'player') {  
                for (const row of enemy.grid) {  
                    for (const e of row) {  
                        if (e.alive && rectIntersect(b, e)) {  
                            e.alive = false;  
                            bullets.splice(i, 1);  
                            explosions.push({ x: e.x, y: e.y, size: 20, alpha: 1 });  
                            score += 10;  
                            break;  
                        }  
                    }  
                }  
            } else if (b.source === 'enemy') {  
                if (rectIntersect(b, player)) {  
                    bullets.splice(i, 1);  
                    explosions.push({ x: player.x, y: player.y, size: 30, alpha: 1 });  
                    gameOver = true;  
                    break;  
                }  
            }  
        }  
    }  

    function updateExplosions() {  
        for (let i = explosions.length - 1; i >= 0; i--) {  
            const e = explosions[i];  
            e.size += 2; e.alpha -= 0.03;  
            if (e.alpha <= 0) explosions.splice(i, 1);  
        }  
    }  

    function rectIntersect(a, b) {  
        return a.x + a.w / 2 > b.x - b.w / 2 &&  
               a.x - a.w / 2 < b.x + b.w / 2 &&  
               a.y + a.h / 2 > b.y - b.h / 2 &&  
               a.y - a.h / 2 < b.y + b.h / 2;  
    }  

    function checkLevelComplete() {  
        for (const row of enemy.grid) { for (const e of row) { if (e.alive) return; } }  
        level++;  
        enemy.speed += 0.2;  
        spawnEnemies();  
    }  

    function drawGameOver() {  
        ctx.fillStyle = 'rgba(0,0,0,0.5)';  
        ctx.fillRect(0,0,WIDTH,HEIGHT);  
        ctx.fillStyle = '#fff';  
        ctx.font = '36px monospace';  
        ctx.textAlign = 'center';  
        ctx.fillText('GAME OVER\nScore: ' + score, WIDTH/2, HEIGHT/2);  
    }  

    function loop() {  
        if (!gameOver) {  
            updatePlayer();  
            updateEnemies();  
            updateBullets();  
            updateExplosions();  
            checkLevelComplete();  

            // Draw  
            ctx.clearRect(0,0,WIDTH,HEIGHT);  
            drawPlayer();  
            drawEnemies();  
            drawBullets();  
            drawExplosions();  
            drawHUD();  

            requestAnimationFrame(loop);  
        } else {  
            drawGameOver();  
        }  
    }  

    loop();  
}

